#include <stdio.h>

int main(void) {
    char text[102];if(!fgets(text,sizeof text,stdin))return 1;
    FILE *file=tmpfile();if(!file)return 1;
    if(fputs(text,file)==EOF || fseek(file,0,SEEK_SET)!=0){fclose(file);return 1;}
    size_t count=0;while(fgetc(file)!=EOF)++count;
    int failed=ferror(file);if(fclose(file)!=0)failed=1;
    if(failed)return 1;printf("%zu\n",count);
    return 0;
}
